SELECT DATE_FORMAT(event_time, 'yyyy-MM') AS event_month, SUM(CASE WHEN event_type = 'search' THEN 1 ELSE 0 END) AS search_count, ROUND((100 * SUM(CASE WHEN event_type = 'click' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_click, COUNT(DISTINCT duration_sec) AS unique_event_types FROM web_events GROUP BY DATE_FORMAT(event_time, 'yyyy-MM') HAVING COUNT(CASE WHEN page = '/cart' THEN 1 END) >= 4;
